<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { ArrowLeft, Plus, Delete, View, Check } from '@element-plus/icons-vue'
import { productRepository } from '../data/repository'
import { generateSkus, currency } from '../utils'
import type { Product } from '../types'

const route=useRoute(),router=useRouter(),active=ref(0),saving=ref(false),preview=ref(false),imageInput=ref<HTMLInputElement>()
const steps=['基本資訊','商品描述','商品分類','商品規格','SKU / 庫存','物流設定','SEO 設定','商品圖片','預覽']
const blank=():Product=>({id:crypto.randomUUID(),name:'',category:'服飾',description:'',status:'draft',price:980,options:[{name:'Color',values:['Black','White']},{name:'Size',values:['S','M']}],skus:[],image:'',weight:300,seoTitle:'',updatedAt:new Date().toISOString()})
const form=reactive<Product>(blank())
onMounted(async()=>{if(route.params.id){const item=await productRepository.get(String(route.params.id));if(item)Object.assign(form,JSON.parse(JSON.stringify(item)))}if(!form.skus.length)form.skus=generateSkus(form.options,[],form.price)})
const totalStock=computed(()=>form.skus.filter(x=>x.enabled).reduce((s,x)=>s+x.stock,0))
function validate(){if(active.value===0&&!form.name.trim()){ElMessage.warning('請輸入商品名稱');return false}if(active.value===3&&form.options.some(x=>!x.name||!x.values.length)){ElMessage.warning('請完成規格名稱與選項');return false}return true}
function next(){if(!validate())return;if(active.value===3)form.skus=generateSkus(form.options,form.skus,form.price);active.value=Math.min(8,active.value+1)}
function addOption(){form.options.push({name:'',values:[]})}
function addValue(index:number,value:string){const text=value.trim();if(text&&!form.options[index].values.includes(text))form.options[index].values.push(text)}
function setImage(file?:File){
  if(!file)return
  if(!file.type.startsWith('image/')){ElMessage.warning('請選擇圖片檔案');return}
  if(file.size>3*1024*1024){ElMessage.warning('圖片不可超過 3 MB');return}
  const reader=new FileReader()
  reader.onload=()=>{form.image=String(reader.result)}
  reader.readAsDataURL(file)
}
function dropImage(event:DragEvent){setImage(event.dataTransfer?.files[0])}
async function save(status:Product['status']='draft'){if(!form.name.trim()){active.value=0;ElMessage.warning('請輸入商品名稱');return}saving.value=true;form.status=status;form.updatedAt=new Date().toISOString();if(!form.image)form.image=`data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="480" height="360"><rect width="100%" height="100%" fill="#315e43"/><text x="50%" y="50%" dominant-baseline="middle" text-anchor="middle" font-family="Arial" font-size="32" fill="white">${form.name}</text></svg>`)}`;await productRepository.save(JSON.parse(JSON.stringify(form)));saving.value=false;ElMessage.success(status==='active'?'商品已上架':'草稿已儲存');router.push('/products')}
</script>

<template>
  <section class="form-page" data-testid="product-form">
    <Teleport to="#page-actions"><div class="header-actions"><el-button :icon="View" @click="preview=true">預覽</el-button><el-button @click="save('draft')">儲存草稿</el-button><el-button type="primary" data-testid="publish-product" :loading="saving" @click="save('active')">儲存並上架</el-button></div></Teleport>
    <button class="back-link" @click="router.push('/products')"><el-icon><ArrowLeft/></el-icon>返回商品列表</button>
    <div class="wizard-layout">
      <aside class="stepper"><div v-for="(step,index) in steps" :key="step" :class="{active:index===active,done:index<active}" @click="active=index"><span><el-icon v-if="index<active"><Check/></el-icon><template v-else>{{index+1}}</template></span><div><strong>{{step}}</strong><small>{{['名稱、售價與狀態','介紹商品特色','選擇商品歸屬','建立尺寸與顏色','設定各組合庫存','重量與配送資訊','搜尋結果呈現','商品展示素材','確認後發布'][index]}}</small></div></div></aside>
      <article class="form-card">
        <header><span>STEP {{active+1}} / 9</span><h2>{{steps[active]}}</h2><p>{{['建立顧客一眼就能理解的商品資訊。','用完整描述建立顧客信任。','分類讓商品更容易被找到。','新增規格，系統將自動建立所有組合。','每個 SKU 都能有自己的價格與庫存。','設定包裹重量與配送方式。','最佳化搜尋引擎顯示內容。','加入商品主圖與展示素材。','最後檢查商品在前台的樣子。'][active]}}</p></header>
        <div v-if="active===0" class="fields"><el-form-item label="商品名稱 *"><el-input v-model="form.name" size="large" placeholder="例如：城市輪廓純棉 T-Shirt" data-testid="product-name"/></el-form-item><div class="two"><el-form-item label="基本售價"><el-input-number v-model="form.price" :min="0" :controls="false"/><span class="suffix">TWD</span></el-form-item><el-form-item label="商品狀態"><el-select v-model="form.status"><el-option label="草稿" value="draft"/><el-option label="上架中" value="active"/><el-option label="已下架" value="inactive"/></el-select></el-form-item></div></div>
        <div v-else-if="active===1" class="fields"><el-form-item label="商品描述"><el-input v-model="form.description" type="textarea" :rows="10" placeholder="描述材質、特色、尺寸與使用情境…" data-testid="product-description"/></el-form-item><small class="helper">建議 80–160 字，清楚說明商品特色與適用情境。</small></div>
        <div v-else-if="active===2" class="fields"><el-form-item label="商品分類"><el-radio-group v-model="form.category" class="category-grid"><el-radio-button v-for="x in ['服飾','包袋','生活','配件']" :key="x" :label="x" :value="x"/></el-radio-group></el-form-item></div>
        <div v-else-if="active===3" class="options"><div v-for="(option,index) in form.options" :key="index" class="option-card"><div class="option-head"><el-input v-model="option.name" placeholder="規格名稱，例如 Color" data-testid="option-name"/><el-button text :icon="Delete" @click="form.options.splice(index,1)"/></div><div class="tag-input"><el-tag v-for="value in option.values" :key="value" closable @close="option.values.splice(option.values.indexOf(value),1)">{{value}}</el-tag><el-input placeholder="輸入後按 Enter" data-testid="option-value" @keyup.enter="addValue(index,($event.target as HTMLInputElement).value);($event.target as HTMLInputElement).value=''"/></div></div><el-button class="add-option" :icon="Plus" @click="addOption">新增一組規格</el-button><div class="combination-note">目前將產生 <strong>{{form.options.reduce((n,x)=>n*Math.max(1,x.values.length),1)}}</strong> 個 SKU 組合</div></div>
        <div v-else-if="active===4" class="sku-section"><div class="sku-summary"><span>SKU 組合 <strong>{{form.skus.length}}</strong></span><span>總庫存 <strong>{{totalStock}}</strong></span></div><el-table :data="form.skus" max-height="410"><el-table-column label="規格組合" min-width="180"><template #default="{row}"><strong>{{Object.values(row.combination).join(' / ')}}</strong></template></el-table-column><el-table-column label="SKU 編號" width="180"><template #default="{row}"><el-input v-model="row.code" data-testid="sku-code"/></template></el-table-column><el-table-column label="售價" width="130"><template #default="{row}"><el-input-number v-model="row.price" :controls="false" :min="0"/></template></el-table-column><el-table-column label="庫存" width="110"><template #default="{row}"><el-input-number v-model="row.stock" :controls="false" :min="0" data-testid="sku-stock"/></template></el-table-column><el-table-column label="啟用" width="70"><template #default="{row}"><el-switch v-model="row.enabled"/></template></el-table-column></el-table></div>
        <div v-else-if="active===5" class="fields"><div class="two"><el-form-item label="商品重量（g）"><el-input-number v-model="form.weight" :min="0"/></el-form-item><el-form-item label="配送溫層"><el-select model-value="常溫"><el-option label="常溫" value="常溫"/><el-option label="冷藏" value="冷藏"/></el-select></el-form-item></div><el-alert title="運費將由結帳時的物流規則自動計算" type="info" show-icon :closable="false"/></div>
        <div v-else-if="active===6" class="fields"><el-form-item label="SEO 標題"><el-input v-model="form.seoTitle" :placeholder="form.name||'商品名稱'" data-testid="seo-title"/></el-form-item><el-form-item label="網址代稱"><el-input :model-value="form.name.toLowerCase().replace(/\s+/g,'-')" disabled/></el-form-item><div class="search-preview"><small>shop.demo › products</small><strong>{{form.seoTitle||form.name||'商品名稱'}}</strong><p>{{form.description||'商品說明會顯示在搜尋結果中。'}}</p></div></div>
        <div v-else-if="active===7" class="fields"><div class="upload-zone" role="button" tabindex="0" data-testid="image-upload" @click="imageInput?.click()" @keydown.enter="imageInput?.click()" @dragover.prevent @drop.prevent="dropImage"><input ref="imageInput" hidden type="file" accept="image/*" @change="setImage(($event.target as HTMLInputElement).files?.[0])"><el-icon><Plus/></el-icon><strong>{{form.image?'圖片已載入，可重新選擇':'拖曳圖片或點擊上傳'}}</strong><span>圖片會安全保存在本機瀏覽器，檔案上限 3 MB</span></div><el-form-item label="示範圖片網址"><el-input v-model="form.image" placeholder="可貼上公開圖片網址" data-testid="image-url"/></el-form-item></div>
        <div v-else class="preview-card"><img :src="form.image||'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22480%22 height=%22360%22%3E%3Crect width=%22100%25%22 height=%22100%25%22 fill=%22%23dfe8df%22/%3E%3C/svg%3E'" alt=""><div><el-tag>{{form.category}}</el-tag><h3>{{form.name||'尚未命名商品'}}</h3><p>{{form.description||'尚未填寫商品描述'}}</p><strong>{{currency(form.price)}}</strong><span>{{form.skus.length}} 個 SKU · {{totalStock}} 件庫存</span></div></div>
        <footer><el-button :disabled="active===0" @click="active--">上一步</el-button><el-button v-if="active<8" type="primary" data-testid="next-step" @click="next">儲存並繼續</el-button><el-button v-else type="primary" data-testid="confirm-publish" @click="save('active')">確認並上架</el-button></footer>
      </article>
    </div>
    <el-dialog v-model="preview" title="商品預覽" width="680"><div class="preview-card"><img :src="form.image" alt=""><div><h3>{{form.name||'尚未命名商品'}}</h3><p>{{form.description}}</p><strong>{{currency(form.price)}}</strong></div></div></el-dialog>
  </section>
</template>
<style scoped>
.back-link{display:flex;align-items:center;gap:6px;border:0;background:transparent;color:#68746c;margin:-60px 0 31px;cursor:pointer}.header-actions{display:flex;gap:9px}.wizard-layout{display:grid;grid-template-columns:260px 1fr;gap:20px}.stepper{background:white;border:1px solid #e4e9e3;border-radius:16px;padding:16px;height:max-content}.stepper>div{position:relative;display:grid;grid-template-columns:34px 1fr;gap:10px;padding:10px 8px;cursor:pointer}.stepper>div:not(:last-child):after{content:'';position:absolute;left:24px;top:45px;width:1px;height:20px;background:#dce3dd}.stepper>div>span{display:grid;place-items:center;width:30px;height:30px;border:1px solid #dbe2dc;border-radius:50%;font-size:12px;color:#8d968f}.stepper>div.active>span{background:#285b3f;border-color:#285b3f;color:white}.stepper>div.done>span{background:#e5f0e8;border-color:#e5f0e8;color:#2c6949}.stepper div div{display:grid;gap:3px}.stepper strong{font-size:12px}.stepper small{font-size:10px;color:#9aa19c}.form-card{background:white;border:1px solid #e4e9e3;border-radius:16px;min-height:620px;display:flex;flex-direction:column}.form-card>header{padding:28px 32px 20px;border-bottom:1px solid #edf0ec}.form-card>header span{font-size:10px;letter-spacing:.12em;color:#b07834;font-weight:800}.form-card>header h2{font-size:23px;margin:7px 0}.form-card>header p{margin:0;color:#848e87;font-size:13px}.fields,.options,.sku-section,.preview-card{padding:28px 32px;flex:1}.two{display:grid;grid-template-columns:1fr 1fr;gap:18px}.suffix{position:absolute;right:12px;top:9px;color:#929a94;font-size:12px}.helper{color:#939b95}.category-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.category-grid :deep(.el-radio-button__inner){width:100%;padding:24px}.option-card{padding:17px;border:1px solid #dfe5df;border-radius:12px;margin-bottom:12px}.option-head{display:grid;grid-template-columns:1fr auto;gap:8px}.tag-input{margin-top:12px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}.tag-input .el-input{width:160px}.add-option{width:100%;border-style:dashed}.combination-note{margin-top:18px;padding:13px;background:#eef5ef;border-radius:10px;color:#3e684d;font-size:12px}.sku-summary{display:flex;gap:25px;margin-bottom:14px;font-size:12px;color:#879089}.sku-summary strong{font-size:17px;color:#25352a;margin-left:5px}.search-preview{padding:18px;border:1px solid #e0e5e0;border-radius:12px;display:grid;gap:6px}.search-preview small{color:#398156}.search-preview strong{color:#305cab;font-size:17px}.search-preview p{font-size:12px;color:#68736b;margin:0}.upload-zone{height:200px;border:1px dashed #aebdb2;border-radius:14px;display:grid;place-content:center;text-align:center;gap:8px;color:#718078;margin-bottom:20px}.upload-zone .el-icon{margin:auto;font-size:24px}.upload-zone span{font-size:11px}.preview-card{display:grid;grid-template-columns:280px 1fr;gap:25px;align-items:center}.preview-card img{width:100%;border-radius:16px;aspect-ratio:4/3;object-fit:cover}.preview-card div{display:grid;gap:10px}.preview-card h3{font-size:25px;margin:0}.preview-card p{font-size:13px;line-height:1.7;color:#707b73}.preview-card strong{font-size:24px;color:#285b3f}.preview-card span{font-size:12px;color:#8a938d}.form-card>footer{margin-top:auto;padding:18px 32px;border-top:1px solid #edf0ec;display:flex;justify-content:space-between}@media(max-width:1000px){.wizard-layout{grid-template-columns:1fr}.stepper{display:flex;overflow:auto}.stepper>div{min-width:145px}.stepper>div:after{display:none}.back-link{margin:0 0 20px}}@media(max-width:650px){.two,.preview-card{grid-template-columns:1fr}.form-card>header,.fields,.options,.sku-section,.preview-card{padding:20px}.header-actions .el-button:first-child{display:none}}
</style>
